function renderHome(){const releases=[...albums.map(a=>({type:'album',data:a,date:a.created_at})),...tracks.filter(t=>!t.album_id).map(t=>({type:'track',data:t,date:t.created_at}))].sort((a,b)=>String(b.date).localeCompare(String(a.date))).slice(0,8);$('homeReleases').innerHTML=releases.map(releaseCard).join('')||'<div class="search-empty">Todavía no hay música.</div>';$('homeArtists').innerHTML=MEMBERS.map(name=>{const a=artistByName(name),p=a.photo_key?mediaUrl(a.photo_key):'';return`<button class="artist-pill-card" onclick="NBCOpenArtist('${encodeURIComponent(name)}')"><span class="artist-avatar" ${coverStyle(p)}>${p?'':esc(initials(name))}</span><strong>${esc(name)}</strong></button>`}).join('')}
