function renderArtistDetail(name){const a=artistByName(name),photo=a.photo_key?mediaUrl(a.photo_key):'',list=tracks.filter(t=>trackArtists(t).includes(name)).sort((x,y)=>String(y.created_at).localeCompare(String(x.created_at))),collabs=list.filter(t=>trackArtists(t).length>1),als=albums.filter(x=>x.artists.includes(name));$('artistDetail').innerHTML=`<button class="page-back" onclick="NBCBack()">${ICONS.back}<span>Volver</span></button><div class="detail-hero"><div class="detail-art round" ${coverStyle(photo)}>${photo?'':esc(initials(name))}</div><div class="detail-copy"><span class="kicker">Artista</span><h2>${esc(name)}</h2><p>${a.bio?esc(a.bio):'Miembro de New BenifaClika.'}</p><div class="statline"><span class="stat">${list.length} temas</span><span class="stat">${collabs.length} colaboraciones</span><span class="stat">${als.length} álbumes</span></div><div class="detail-actions"><button class="primary-action" onclick="NBCPlayArtist('${encodeURIComponent(name)}')">${ICONS.play} Reproducir artista</button>${user?`<button class="ghost-action" onclick="NBCEditArtist('${encodeURIComponent(name)}')">${EDIT_ICON} Editar perfil</button>`:''}</div></div></div>${als.length?`<section class="content-section"><div class="section-head"><h2>Álbumes</h2></div><div class="card-grid">${als.map(albumCard).join('')}</div></section>`:''}${collabs.length?`<section class="content-section"><div class="section-head"><h2>Colaboraciones</h2></div><div class="track-list">${collabs.map(trackRow).join('')}</div></section>`:''}<section class="content-section"><div class="section-head"><h2>Todas las canciones</h2></div><div class="track-list">${list.map(trackRow).join('')||'<div class="search-empty">Sin canciones.</div>'}</div></section>`}
function searchData(v){const n=norm(v);if(!n)return{tracks:[],albums:[],artists:[]};return{tracks:tracks.filter(t=>norm(`${t.title} ${artistText(t)} ${albumById(t.album_id)?.title||''}`).includes(n)),albums:albums.filter(a=>norm(`${a.title} ${a.artists.join(' ')}`).includes(n)),artists:MEMBERS.filter(name=>norm(name).includes(n)||tracks.some(t=>trackArtists(t).includes(name)&&norm(`${t.title} ${albumById(t.album_id)?.title||''}`).includes(n)))}}
function renderSuggestions(v){const box=$('searchSuggest');if(!v.trim()){box.classList.remove('show');box.innerHTML='';return}const r=searchData(v);const group=(h,items,fn)=>items.length?`<div class="suggest-group"><strong>${h}</strong>${items.slice(0,4).map(fn).join('')}</div>`:'';box.innerHTML=group('Artistas',r.artists,n=>{const p=artistByName(n).photo_key?mediaUrl(artistByName(n).photo_key):'';return`<button class="suggest-item" data-a="${encodeURIComponent(n)}"><span class="suggest-thumb round" ${coverStyle(p)}>${p?'':esc(initials(n))}</span><span><strong>${esc(n)}</strong><span>Artista</span></span></button>`})+group('Álbumes',r.albums,a=>`<button class="suggest-item" data-al="${a.id}"><span class="suggest-thumb" ${coverStyle(albumCover(a))}>${albumCover(a)?'':ALBUM_FALLBACK}</span><span><strong>${esc(a.title)}</strong><span>${esc(a.artists.join(' × '))}</span></span></button>`)+group('Canciones',r.tracks,t=>`<button class="suggest-item" data-t="${t.id}"><span class="suggest-thumb" ${coverStyle(trackCover(t))}>${trackCover(t)?'':esc(initials(trackArtists(t)[0]))}</span><span><strong>${esc(t.title)}</strong><span>${esc(artistText(t))}</span></span></button>`)+`<button class="suggest-more" id="showSearchAll">Ver todos los resultados</button>`;box.classList.add('show');$$('[data-a]',box).forEach(b=>b.onclick=()=>{box.classList.remove('show');NBCOpenArtist(b.dataset.a)});$$('[data-al]',box).forEach(b=>b.onclick=()=>{box.classList.remove('show');NBCOpenAlbum(b.dataset.al)});$$('[data-t]',box).forEach(b=>b.onclick=()=>{box.classList.remove('show');NBCPlayTrack(b.dataset.t)});$('showSearchAll').onclick=()=>openSearch(v)}
function openSearch(v){$('searchSuggest').classList.remove('show');$('globalSearch').value=v;showView('search');pushRoute({view:'search',query:v})}function renderSearch(v){const r=searchData(v),f=searchFilter;$('searchSummary').textContent=v?`Resultados para “${v}”`:'Escribe algo para buscar';let h='';if(f==='all'||f==='artists')h+=`<section class="search-group"><div class="search-group-head"><h3>Artistas</h3><span>${r.artists.length}</span></div><div class="card-grid">${r.artists.map(artistCard).join('')||'<div class="search-empty">Sin artistas.</div>'}</div></section>`;if(f==='all'||f==='albums')h+=`<section class="search-group"><div class="search-group-head"><h3>Álbumes</h3><span>${r.albums.length}</span></div><div class="card-grid">${r.albums.map(albumCard).join('')||'<div class="search-empty">Sin álbumes.</div>'}</div></section>`;if(f==='all'||f==='tracks')h+=`<section class="search-group"><div class="search-group-head"><h3>Canciones</h3><span>${r.tracks.length}</span></div><div class="track-list">${r.tracks.map(trackRow).join('')||'<div class="search-empty">Sin canciones.</div>'}</div></section>`;$('searchResults').innerHTML=h}
let searchTimer;$('globalSearch').oninput=e=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>renderSuggestions(e.target.value),100)};$('globalSearch').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();openSearch(e.target.value)}};document.addEventListener('click',e=>{if(!e.target.closest('.search-wrap'))$('searchSuggest').classList.remove('show')});$$('#searchFilters .chip').forEach(b=>b.onclick=()=>{$$('#searchFilters .chip').forEach(x=>x.classList.remove('active'));b.classList.add('active');searchFilter=b.dataset.filter;renderSearch($('globalSearch').value)});
function shuffleArray(a){const o=[...a];for(let i=o.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[o[i],o[j]]=[o[j],o[i]]}return o}
function sourceIds(source){if(source.type==='album')return(albumById(source.id)?.tracks||[]).map(t=>t.id);if(source.type==='artist')return tracks.filter(t=>trackArtists(t).includes(source.id)).map(t=>t.id);return tracks.map(t=>t.id)}
function appendRadio(count=28){const seen=new Set(playback.queue),pool=tracks.map(t=>t.id).filter(id=>!seen.has(id));let candidates=playback.shuffle?shuffleArray(pool):pool;if(!candidates.length){playback.radioSeen.clear();candidates=tracks.map(t=>t.id).filter(id=>id!==currentTrack?.id);if(playback.shuffle)candidates=shuffleArray(candidates)}playback.queue.push(...candidates.slice(0,count))}
function buildQueue(source,startId=null){let ids=sourceIds(source);if(playback.shuffle)ids=shuffleArray(ids);if(startId&&ids.includes(startId)){const i=ids.indexOf(startId);ids=[startId,...ids.slice(0,i),...ids.slice(i+1)]}playback.queue=ids;playback.pos=0;playback.primaryLength=ids.length;playback.source=source;playback.history=[];if(playback.queue.length<10)appendRadio();}
