function setPlayState(){const loading=!!currentTrack&&(isStarting||isBuffering),playing=!!currentTrack&&!audio.paused&&!audio.ended&&!loading;['playBtn','nowPlayBtn'].forEach(id=>{const b=$(id);b?.classList.toggle('loading',loading);const i=b?.querySelector('.play-icon');if(i)i.innerHTML=playing?ICONS.pause:ICONS.play;b?.setAttribute('aria-label',playing?'Pausar':'Reproducir');b?.setAttribute('title',playing?'Pausar':'Reproducir')});$('player').classList.toggle('playing',playing);$$('[data-track-id]').forEach(r=>r.classList.toggle('playing',playing&&r.dataset.trackId===currentTrack?.id))}
