$('albumEditForm').onsubmit=async e=>{e.preventDefault();const id=$('albumEditingId')?.value,a=albumById(id);if(!a)return;const title=$('albumEditTitle').value.trim(),coverFile=$('albumEditCover').files[0],existingRows=$$('[data-edit-track]',$('albumEditFields')),newRows=$$('[data-new-track]',$('albumEditFields'));if(!title)return $('albumEditStatus').textContent='Pon un nombre al álbum.';if(existingRows.filter(r=>!albumRemoveIds.has(r.dataset.editTrack)).length+newRows.length<1)return $('albumEditStatus').textContent='Un álbum necesita al menos una canción.';$('albumEditStatus').innerHTML='<span class="spinner"></span>Guardando…';uploadBusy=true;const uploaded=[];try{let cover_key=a.cover_key;if(coverFile){const up=await uploadFile(coverFile,'cover');cover_key=up.key;uploaded.push(up.key)}const existing=[];for(const row of existingRows){if(albumRemoveIds.has(row.dataset.editTrack))continue;const titleValue=q('.album-edit-title',row).value.trim(),artistsSel=selectedArtists(q('.album-edit-artists',row)),track_number=Number(q('.album-edit-number',row).value)||1;if(!titleValue||!artistsSel.length)throw new Error('Revisa las canciones existentes.');existing.push({id:row.dataset.editTrack,title:titleValue,artists:artistsSel,track_number})}const add=[];for(let i=0;i<newRows.length;i++){const row=newRows[i],file=albumEditFiles[i],titleValue=q('.album-new-title',row).value.trim(),artistsSel=selectedArtists(q('.album-new-artists',row));if(!file||!titleValue||!artistsSel.length)throw new Error(`Revisa la nueva canción ${i+1}.`);$('albumEditStatus').innerHTML=`<span class="spinner"></span>Subiendo ${i+1}/${newRows.length}: ${esc(titleValue)}`;const duration=await audioDuration(file),up=await uploadFile(file,'audio');uploaded.push(up.key);add.push({title:titleValue,artists:artistsSel,audio_key:up.key,duration_seconds:duration})}await api(`/api/albums/${encodeURIComponent(id)}`,{method:'PUT',body:JSON.stringify({title,cover_key,existing,add,remove_ids:[...albumRemoveIds]})});await loadAll();loadStorageStatus();renderAlbumEdit(id);toast('Álbum actualizado.');$('albumEditStatus').textContent=''}catch(err){await rollbackKeys(uploaded);$('albumEditStatus').textContent=err.message}finally{uploadBusy=false}};
$('deleteAlbumBtn').onclick=async()=>{const id=$('albumEditingId')?.value,a=albumById(id);if(!a||!confirm(`¿Borrar el álbum “${a.title}” y todas sus canciones?`))return;try{await api(`/api/albums/${encodeURIComponent(id)}`,{method:'DELETE'});closeModal('albumEditModal');await loadAll();loadStorageStatus();showView('albums');toast('Álbum borrado.')}catch(e){toast(e.message)}};
function fillArtists(){ $('profileArtist').innerHTML=MEMBERS.map(n=>`<option value="${esc(n)}">${esc(n)}</option>`).join('') }function refreshProfile(){const name=$('profileArtist').value,a=artistByName(name),p=a.photo_key?mediaUrl(a.photo_key):'';$('profilePreview').style.backgroundImage=p?`url("${p}")`:'';$('profilePreview').textContent=p?'':initials(name);$('profileBio').value=a.bio||'';$('removeProfilePhotoBtn').style.display=a.photo_key?'':'none'}function openProfile(name=null){fillArtists();$('profileArtist').value=name&&MEMBERS.includes(name)?name:MEMBERS[0];$('profilePhoto').value='';$('profileStatus').textContent='';refreshProfile();openModal('profileModal')}$('profilesAction').onclick=()=>{closeModal('editMenuModal');openProfile()};$('profileArtist').onchange=refreshProfile;window.NBCEditArtist=e=>openProfile(decodeURIComponent(e));$('profilePhoto').onchange=e=>{const f=e.target.files[0];if(f){const u=URL.createObjectURL(f);$('profilePreview').style.backgroundImage=`url("${u}")`;$('profilePreview').textContent=''}};
$('profileForm').onsubmit=async e=>{e.preventDefault();const name=$('profileArtist').value,bio=$('profileBio').value.trim(),file=$('profilePhoto').files[0],a=artistByName(name);$('profileStatus').innerHTML='<span class="spinner"></span>Guardando…';const uploaded=[];try{let photo_key=a.photo_key;if(file){const up=await uploadFile(file,'artist');photo_key=up.key;uploaded.push(up.key)}await api(`/api/artists/${encodeURIComponent(name)}`,{method:'PUT',body:JSON.stringify({bio,photo_key})});await loadAll();loadStorageStatus();refreshProfile();toast(`Perfil de ${name} actualizado.`);$('profileStatus').textContent=''}catch(err){await rollbackKeys(uploaded);$('profileStatus').textContent=err.message}};$('removeProfilePhotoBtn').onclick=async()=>{const name=$('profileArtist').value;if(!confirm(`¿Quitar la foto de ${name}?`))return;try{await api(`/api/artists/${encodeURIComponent(name)}`,{method:'PUT',body:JSON.stringify({bio:$('profileBio').value.trim(),photo_key:null})});await loadAll();loadStorageStatus();refreshProfile();toast('Foto eliminada.')}catch(e){toast(e.message)}};
window.addEventListener('beforeunload',e=>{if(uploadBusy){e.preventDefault();e.returnValue=''}});
function isStandalone(){return matchMedia('(display-mode: standalone)').matches||navigator.standalone===true}function isMobileInstallContext(){return matchMedia('(max-width:760px)').matches||/Android|iPhone|iPad|iPod/i.test(navigator.userAgent)}function refreshInstall(){const b=$('installBtn');if(!b)return;if(isStandalone()){b.style.display='none';return}b.style.display=(deferredPrompt||isMobileInstallContext())?'inline-flex':'none'}function showInstallHelp(){const ios=/iPhone|iPad|iPod/i.test(navigator.userAgent),title=$('installHelpTitle'),text=$('installHelpText');if(ios){title.textContent='Instalar en iPhone / iPad';text.textContent='Abre esta página en Safari, pulsa Compartir y elige “Añadir a pantalla de inicio”.'}else{title.textContent='Instalar en el móvil';text.textContent='Abre el menú de tu navegador y elige “Instalar aplicación” o “Añadir a pantalla de inicio”.'}openModal('installModal')}window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredPrompt=e;refreshInstall()});window.addEventListener('appinstalled',()=>{deferredPrompt=null;refreshInstall();toast('New BenifaClika instalada.')});window.addEventListener('pageshow',refreshInstall);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshInstall()});try{matchMedia('(display-mode: standalone)').addEventListener('change',refreshInstall)}catch{}$('installBtn').onclick=async()=>{if(!deferredPrompt){showInstallHelp();return}const p=deferredPrompt;deferredPrompt=null;await p.prompt();refreshInstall()};
if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});window.addEventListener('online',loadAll);document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select'))return;if(e.code==='Space'){e.preventDefault();audio.paused?startCurrent():audio.pause()}else if(e.key==='ArrowRight'&&audio.duration)audio.currentTime=Math.min(audio.duration,audio.currentTime+5);else if(e.key==='ArrowLeft')audio.currentTime=Math.max(0,audio.currentTime-5)});
(async()=>{await Promise.all([loadAll(),authStatus()]);const route=routeFromUrl();history.replaceState({nbc:true,route},'',location.href);applyRoute(route,false);refreshInstall()})();
